INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22011$nota-0264$m22011$, $m22012$Exercise Physiology McArdle.pdf$m22012$, $m22013$632$m22013$, $m22014$Whole-body precooling (core temperature decrease of 0.7°C [1.26°F]) with up to 60 min immersion in water at 23.5°C (74°F)... increases subsequent endurance in a hot, humid environment. Time to exhaustion inversely related to initial body temperature (lowered via precooling) and directly related to the rate of heat storage.$m22014$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22015$nota-0264$m22015$, $m22016$Exercise Physiology McArdle.pdf$m22016$, $m22017$632$m22017$, $m22018$whole-body precooling of the skin by 5 to 6°C (9–10.8°F) without reduction in core temperature reduced thermal strain and increased distance cycled in 30 min under warm, humid conditions.$m22018$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22019$nota-0275$m22019$, $m22020$Exercise Physiology McArdle.pdf$m22020$, $m22021$610$m22021$, $m22022$Endurance training at altitude does not improve subsequent sea-level exercise performance... Sea-level exercise performance does not improve after living at altitude when VO2max serves as the improvement criterion.$m22022$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22023$nota-0275$m22023$, $m22024$Exercise Physiology McArdle.pdf$m22024$, $m22025$612$m22025$, $m22026$Athletes who lived at 2500 m but returned regularly to lower altitudes (1000 to 1250 m; 3280 to 4100 ft) to train at near–sea-level intensity (i.e., live high–train low) showed greater average increases in VO2max and 5000-m run performance than athletes who lived and trained only at 2500 m or those who lived and trained only at sea level.$m22026$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m22027$nota-0275$m22027$, $m22028$nota-0134$m22028$, $m22029$complementa$m22029$, $m22030$esclarece um ponto que a nota-0134 não abordava: o efeito do treino EM altitude (não apenas a comparação de desempenho medido em altitude) sobre o desempenho subsequente ao nível do mar$m22030$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22031$nota-0001$m22031$, $m22032$Training and Racing with a Power Meter.pdf$m22032$, $m22033$22$m22033$, $m22034$A heart rate monitor does not tell you how much you are improving on your bicycle; it just tells you how fast your heart is pumping.$m22034$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22035$nota-0001$m22035$, $m22036$Training and Racing with a Power Meter.pdf$m22036$, $m22037$23$m22037$, $m22038$If your heart rate is normally 165 beats per minute (bpm) when you are riding at 280 watts, then after seven days of hard training it may only be 158 bpm at 280 watts because of your fatigue.$m22038$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22039$nota-0008$m22039$, $m22040$Training and Racing with a Power Meter.pdf$m22040$, $m22041$42$m22041$, $m22042$Power = Force × Speed$m22042$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22043$nota-0009$m22043$, $m22044$Training and Racing with a Power Meter.pdf$m22044$, $m22045$44$m22045$, $m22046$these noncircular chainrings will show an increase in calculated power output for any power meter measuring angular velocity at the crank or pedals.$m22046$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22047$nota-0009$m22047$, $m22048$Training and Racing with a Power Meter.pdf$m22048$, $m22049$45$m22049$, $m22050$This does in fact speed up the crank within a single rpm and because of this increase in speed within the single rpm, causes the power output to be inflated by up to 10–20 watts on average, depending on how oval the chainrings are.$m22050$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22051$nota-0010$m22051$, $m22052$Training and Racing with a Power Meter.pdf$m22052$, $m22053$40$m22053$, $m22054$One of the advantages of a hub-based system is that it measures the wattage that is actually getting to the road, after it has traveled from the crank through the drivetrain. This causes the power to be about 5–10 watts lower than if it were measured by a power meter at the crank or pedals.$m22054$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22055$nota-0011$m22055$, $m22056$Training and Racing with a Power Meter.pdf$m22056$, $m22057$38$m22057$, $m22058$typical leg-strength discrepancies amount to roughly 5 percent for most adults. While it doesn't seem like much, when your functional threshold power is 300 watts, a 15-watt discrepancy could be very misleading.$m22058$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22059$nota-0012$m22059$, $m22060$Training and Racing with a Power Meter.pdf$m22060$, $m22061$46$m22061$, $m22062$Always record your power-meter data using the highest recording rate. This typically means that data is recorded every second.$m22062$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22063$nota-0012$m22063$, $m22064$Training and Racing with a Power Meter.pdf$m22064$, $m22065$47$m22065$, $m22066$Garmin head units default to a rate described as \"smart recording\"... this is not ideal for capturing power-meter data, and if you don't change the setting you will miss out on a tremendous amount of power data.$m22066$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22067$nota-0013$m22067$, $m22068$Training and Racing with a Power Meter.pdf$m22068$, $m22069$47$m22069$, $m22070$Most head units will let you configure this as 3-second, 5-second, 10-second, 20-second, etc. rolling averages of the data to be displayed... For 90 percent of your training we recommend using a 3- or 5-second rolling average. A 10-second rolling average might be more beneficial in a time trial.$m22070$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22071$nota-0014$m22071$, $m22072$Training and Racing with a Power Meter.pdf$m22072$, $m22073$47$m22073$, $m22074$Power meters need to be \"zeroed\" just like the weight scale in your bathroom. If your scale reads \"+5 lb.\" before you step on it, well, your weight will be heavier by 5 pounds. The same goes for power meters.$m22074$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m22075$nota-0014$m22075$, $m22076$Training and Racing with a Power Meter.pdf$m22076$, $m22077$48$m22077$, $m22078$We suggest that you zero your power meter before every ride or after any kind of trauma... There is nothing worse than coming home from a ride where you put out more power than you ever have, to download the data and realize you forgot to zero your power meter and all your data is skewed by +23 watts.$m22078$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m22079$nota-0014$m22079$, $m22080$nota-0015$m22080$, $m22081$complementa$m22081$, $m22082$ambas tratam de erro/artefato de medição de potência; 0014 é erro sistemático (toda a atividade deslocada), 0015 é erro pontual (amostra única)$m22082$)
